package com.tapeverify.copilot.config;
import com.tapeverify.copilot.security.JwtAuthenticationFilter; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){ return new BCryptPasswordEncoder(); }
 @Bean SecurityFilterChain securityFilterChain(HttpSecurity http, JwtAuthenticationFilter jwt) throws Exception { return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/v1/auth/login","/actuator/health","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().requestMatchers("/api/v1/admin/**").hasRole("ADMIN").requestMatchers(HttpMethod.GET,"/api/v1/verified-loans/**","/api/v1/summary","/api/v1/audit/**").hasAnyRole("DATA_CONSUMER","REVIEWER","ADMIN").requestMatchers(HttpMethod.GET,"/api/v1/exceptions/**").hasAnyRole("REVIEWER","ADMIN").requestMatchers("/api/v1/loans/ingest","/api/v1/batches/**").hasAnyRole("OPERATOR","REVIEWER","ADMIN").requestMatchers("/api/v1/loans/*/resolve","/api/v1/loans/*/review","/api/v1/loans/*/review-actions","/api/v1/loans/*/exceptions/**","/api/v1/loans/*/explain","/api/v1/ai/**").hasAnyRole("REVIEWER","ADMIN").requestMatchers("/api/v1/**").hasAnyRole("OPERATOR","REVIEWER","DATA_CONSUMER","ADMIN").anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build(); }
}
